Creating a custom WordPress block is a great way to extend the functionality of the Gutenberg editor.

The modern standard for creating blocks is using the **React** library with the **@wordpress/block-editor** package.

Here is a step-by-step guide to creating a block that contains a Heading, Paragraph, and Image.

### Prerequisites
You need a basic understanding of JavaScript and React. You can do this in a local environment (like VS Code) or inside the WordPress Playground.

---

### Step 1: Create the Block File
Create a new file named `my-custom-block.js`.

### Step 2: Define the Block Metadata
We need to tell WordPress what this block is called, what icon to use, and what category it belongs to.

```javascript
import { registerBlockType } from '@wordpress/blocks';
import { Icon } from '@wordpress/icons';
import { __ } from '@wordpress/i18n';

// 1. Register the block
registerBlockType('my-custom-block/my-custom-block', {
    title: __('My Custom Block', 'my-custom-block'),
    icon: 'image-alt', // You can use any icon name from the WordPress icon library
    category: 'design',
    description: __('A block with a heading, paragraph, and image.', 'my-custom-block'),

    // 2. Define the attributes (data)
    attributes: {
        heading: {
            type: 'string',
            default: 'My Custom Heading'
        },
        content: {
            type: 'string',
            default: 'This is the paragraph content.'
        },
        imageUrl: {
            type: 'string',
            default: 'https://via.placeholder.com/600x400'
        }
    },

    // 3. Define the Editable UI (The React Component)
    edit: function(props) {
        const { attributes, setAttributes } = props;

        return (
            <div className="my-custom-block-wrapper">
                {/* Heading Input */}
                <div className="mb-2">
                    <label>Heading</label>
                    <input 
                        type="text" 
                        value={attributes.heading} 
                        onChange={(e) => setAttributes({ heading: e.target.value })} 
                    />
                </div>

                {/* Paragraph Input */}
                <div className="mb-2">
                    <label>Paragraph</label>
                    <textarea 
                        rows="3"
                        value={attributes.content} 
                        onChange={(e) => setAttributes({ content: e.target.value })} 
                    />
                </div>

                {/* Image URL Input */}
                <div className="mb-2">
                    <label>Image URL</label>
                    <input 
                        type="text" 
                        value={attributes.imageUrl} 
                        onChange={(e) => setAttributes({ imageUrl: e.target.value })} 
                    />
                </div>

                {/* Preview Area */}
                <div className="preview-area">
                    <h2>{attributes.heading}</h2>
                    <p>{attributes.content}</p>
                    <img src={attributes.imageUrl} alt="Custom Block Image" />
                </div>
            </div>
        );
    },

    // 4. Define the Save Function (What gets stored in the DB)
    save: function(props) {
        const { attributes } = props;

        return (
            <div className="my-custom-block-wrapper">
                <h2>{attributes.heading}</h2>
                <p>{attributes.content}</p>
                <img src={attributes.imageUrl} alt="Custom Block Image" />
            </div>
        );
    }
});
