```javascript
const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const Peer = require('peerjs');

const app = express();
const server = http.createServer(app);
const io = new Server(server);

// Serve static files from the 'public' directory
app.use(express.static('public'));

// Create a PeerJS server instance
const peerServer = new Peer({
  // In production, you would use a cloud peer server or your own IP
  // For local testing, we use the default cloud server
  debug: 2
});

// Store active peers in memory (simple implementation)
const peers = {};

peerServer.on('open', (id) => {
  console.log(`Peer server started with ID: ${id}`);
});

peerServer.on('connection', (conn) => {
  const peerId = conn.peer;

  // Create a Socket.io connection for this peer
  const socket = io.sockets.adapter.rooms.get(peerId) || io.sockets.adapter.rooms.get('all');

  // If the peer is new, create a socket for them
  if (!peers[peerId]) {
    const socket = io.sockets.sockets[peerId];
    peers[peerId] = socket;

    console.log(`New peer connected: ${peerId}`);

    // Send the peer's ID to the client so they can join
    socket.emit('peer-id', peerId);
  }
});

server.listen(3000, () => {
