I will break this down into the three specific parts you requested.

---

### Part 1: Backend (Node.js)
We will use **Express** for the server and **PostgreSQL** for the database. We will use the `pg` library for database connections.

**Prerequisites:**
`npm install express pg cors dotenv`

#### 1. Database Schema (SQL)
First, let's define the table structure.

```sql
CREATE TABLE hotels (
    id SERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    city VARCHAR(100),
    country VARCHAR(100),
    rating DECIMAL(3, 2)
);

-- Sample Data
INSERT INTO hotels (name, city, country, rating) VALUES
('Grand Hotel', 'Paris', 'France', 4.5),
('Grand Hotel', 'London', 'UK', 4.2),
('Grand Hotel', 'New York', 'USA', 4.8),
('Sunset Resort', 'Miami', 'USA', 4.9),
('Sunset Resort', 'Cancun', 'Mexico', 4.7),
('City Inn', 'Berlin', 'Germany', 3.8);
```

#### 2. The API Endpoint (`server.js`)
This endpoint accepts a `query` parameter. It performs a "LIKE" search on the name and returns results sorted by relevance (name match first, then rating).

```javascript
const express = require('express');
const { Pool } = require('pg');
const cors = require('cors');
require('dotenv').config();

const app = express();
app.use(cors());
app.use(express.json());

// Database Connection
const pool = new Pool({
  user: process.env.DB_USER,
  host: process.env.DB_HOST,
  database: process.env.DB_NAME,
  password: process.env.DB_PASSWORD,
  port: process.env.DB_PORT,
});

// Autocomplete Endpoint
app.get('/api/hotels', async (req, res) => {
  const { query } = req.query;

  if (!query || query.length < 2) {
    return res.status(400).json({ error: "Query must be at least 2 characters" });
  }

  try {
    // SQL Injection Prevention: Use parameterized queries
    const queryText = `
      SELECT id, name, city, country, rating 
      FROM hotels 
      WHERE name ILIKE $1 
      ORDER BY name ILIKE $1 DESC, rating DESC
      LIMIT 10
    `;

    const values = [`%${query}%`]; // ILIKE is case-insensitive

    const result = await pool.query(queryText, values);

    // Map results to a cleaner format
    const hotels = result.rows.map(h => ({
      id: h.id,
      name: h.name,
      location: `${h.city}, ${h.country}`,
      rating: h.rating
    }));

    res.json(hotels);

  } catch (error) {
    console.error('Database Error:', error);
    res.status(500).json({ error: 'Server error' });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

