)

// AnsibleService implements the PlaybookServiceServer interface
type AnsibleService struct {
	PlaybookServiceServer
}

// ExecutePlaybook handles the gRPC request
func (s *AnsibleService) ExecutePlaybook(ctx context.Context, req *playbook.PlaybookRequest) (*playbook.PlaybookResponse, error) {
	// 1. Validate inputs
	if req.PlaybookPath == "" {
		return nil, status.Error(codes.InvalidArgument, "playbook_path is required")
